            "store_global_scatter",
            dst_shape=dst.shape,
            dst_dtype=dst.dtype,
            indices=indices,
            values=values,
            dim=dim,
        )
        return StoreGlobalScatterInst(output=None, inputs=(dst, indices, values), dim=dim)


