# Scan opcodes. `add`/`mul`/`max`/`min` accept any numeric dtype; the bitwise
# variants (`and`/`or`/`xor`) require an integer dtype.
SCAN_OPS: tuple[str, ...] = ("add", "mul", "max", "min", "and", "or", "xor")
SCAN_BITWISE_OPS: tuple[str, ...] = ("and", "or", "xor")


@dataclass(frozen=True, eq=False)
class ScanInst(Instruction):
    """Tile-level prefix scan along a single axis.

    Output shape == input shape (no dim collapse, unlike reduce). The scan is
    performed independently for each non-``dim`` coordinate; along ``dim`` the
    result at position ``i`` is the ⊕-combination of input positions
    ``0..i`` (inclusive) or ``0..i-1`` (exclusive), with the op's identity at
    the boundary.
    """

    dim: int
    op: str
    exclusive: bool
    VALID_OPS: ClassVar[tuple[str, ...]] = SCAN_OPS

    @staticmethod
    def create(
        x: RegisterTensor,
        *,
        dim: int,
        op: str,
        exclusive: bool,
        output: RegisterTensor,
    ) -> ScanInst:

    from tilus.ir.layout.ops.utils import get_mode_groups

    return get_mode_groups(self.shape, self.mode_shape)

@cached_property
def spatial_shape(self) -> list[int]:
    return [self.mode_shape[i] if i >= 0 else -i for i in self.spatial_modes]

@cached_property
def local_shape(self) -> list[int]:
    return [self.mode_shape[i] for i in self.local_modes]

@cached_property
def local_size(self) -> int:
    return prod(self.local_shape)

@cached_property
def spatial_size(self) -> int:
    return prod(self.spatial_shape)

@cached_property
def size(self) -> int:
    return prod(self.shape)

def spatial_mfunction(self) -> MultiFunction:
    """Get the multi-function that maps the global indices to the spatial indices (serialized)."""
    return multi_function(
        shape=self.shape,
        mode_shape=self.mode_shape,
